<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import LoadingState from '../components/LoadingState.vue'; import QuestionCard from '../components/QuestionCard.vue'; import TtsControls from '../components/TtsControls.vue'; import { useExamStore } from '../stores/exam'; import { getTtsEngine } from '../services/ttsEngine'; import type { ChoiceLabel, QuestionGroup, ToeicTest } from '../types/exam'
const props=defineProps<{section?:string}>(); const route=useRoute(),router=useRouter(),store=useExamStore(),testId=String(route.params.testId); const test=ref<ToeicTest>(); const started=ref(false),position=ref(0)
onMounted(async()=>{try{test.value=await store.ensureTest(testId)}catch{}}); onBeforeUnmount(()=>getTtsEngine().cancelSpeech())
const groups=computed<QuestionGroup[]>(()=>{const all=test.value?.parts.flatMap(p=>p.groups)??[]; return props.section==='listening'?all.filter(g=>g.part<=4):props.section==='reading'?all.filter(g=>g.part>=5):all}); const current=computed(()=>groups.value[position.value]); const total=computed(()=>test.value?.parts.flatMap(p=>p.groups.flatMap(g=>g.questions)).length??0); const currentNumber=computed(()=>groups.value.slice(0,position.value).reduce((n,g)=>n+g.questions.length,0)+1); const percent=computed(()=>total.value?Math.round((Math.min(currentNumber.value,total.value)/total.value)*100):0)
function choose(id:number,value:ChoiceLabel){store.answer(testId,id,value)} function next(){if(position.value<groups.value.length-1){getTtsEngine().cancelSpeech();position.value++;window.scrollTo({top:0,behavior:'smooth'})}} function previous(){if(current.value?.part&&current.value.part<=4)return;if(position.value>0)position.value--} function submit(){if(!test.value)return; store.submit(test.value); getTtsEngine().cancelSpeech(); router.push(`/test/${testId}/result`)}
</script>
<template><div class="page"><LoadingState :loading="store.loading" :error="store.error"/><section v-if="test&&!started" class="start-screen"><p class="eyebrow">Exam mode</p><h1>Ready when you are.</h1><p class="lead">Audio never starts automatically. Tap the button below, then use Play audio for each Listening set. Answers, transcripts, and explanations stay hidden until submission.</p><ul><li>{{ total }} original questions in this {{ test.metadata.demo?'demonstration':'full' }} test</li><li>Listening navigation only moves forward</li><li>Reading allows previous/next navigation</li><li>Raw scores only; no unofficial TOEIC conversion</li></ul><button class="button primary large" @click="started=true;store.clearAnswers(testId)">Start test</button></section><template v-else-if="test&&current"><div class="exam-bar"><div><span>Question progress</span><strong>{{ currentNumber }} / {{ total }}</strong></div><div class="progress"><i :style="{width:`${percent}%`}"/></div><span>{{ percent }}%</span></div><div class="workspace-header"><div><p class="eyebrow">{{ current.part<=4?'Listening':'Reading' }}</p><h1>Part {{ current.part }}</h1></div><span class="pill">Exam mode</span></div><TtsControls v-if="current.part<=4" :lines="current.speech.length?current.speech:current.questions[0].speech" exam/><section class="questions-stack exam-stack"><QuestionCard v-for="question in current.questions" :key="question.id" :question="question" :model-value="store.answers[testId]?.[question.id]" exam @update:model-value="choose(question.id,$event)"/></section><div class="pager sticky"><button :disabled="position===0||current.part<=4" @click="previous">← Previous</button><button v-if="position<groups.length-1" class="primary" @click="next">Next →</button><button v-else class="primary danger" @click="submit">Submit test</button></div></template></div></template>
